<?php $page_title='Reports'; require_once __DIR__.'/../includes/header.php'; require_perm($pdo,'reports','can_view'); $type=clean($_GET['type']??'sales'); $from=clean($_GET['from']??date('Y-m-01')); $to=clean($_GET['to']??date('Y-m-d'));
$sales=[]; $purchases=[]; $stock=[]; $moves=[];
if($type==='sales'){ $s=$pdo->prepare("SELECT s.*, c.name as cust FROM sales s JOIN customers c ON c.id=s.customer_id WHERE s.sale_date BETWEEN ? AND ? ORDER BY s.id DESC"); $s->execute([$from,$to]); $sales=$s->fetchAll(); }
if($type==='purchases'){ $s=$pdo->prepare("SELECT p.*, sup.name as supp FROM purchases p JOIN suppliers sup ON sup.id=p.supplier_id WHERE p.purchase_date BETWEEN ? AND ? ORDER BY p.id DESC"); $s->execute([$from,$to]); $purchases=$s->fetchAll(); }
if($type==='inventory'){ $stock=$pdo->query("SELECT p.sku,p.name, w.name as wname, s.quantity FROM stock s JOIN products p ON p.id=s.product_id JOIN warehouses w ON w.id=s.warehouse_id ORDER BY p.name")->fetchAll(); }
if($type==='movements'){ $moves=$pdo->query("SELECT m.*, p.name as pname, w.name as wname FROM stock_movements m JOIN products p ON p.id=m.product_id JOIN warehouses w ON w.id=m.warehouse_id ORDER BY m.id DESC LIMIT 200")->fetchAll(); }
?>
<div class="card p-3 mb-3"><form class="row g-2"><div class="col-md-3"><select name="type" class="form-select"><option value="sales" <?= $type==='sales'?'selected':'' ?>>Sales Report</option><option value="purchases" <?= $type==='purchases'?'selected':'' ?>>Purchases Report</option><option value="inventory" <?= $type==='inventory'?'selected':'' ?>>Inventory Report</option><option value="movements" <?= $type==='movements'?'selected':'' ?>>Stock Movements</option></select></div><div class="col-md-3"><input type="date" name="from" value="<?= e($from) ?>" class="form-control"></div><div class="col-md-3"><input type="date" name="to" value="<?= e($to) ?>" class="form-control"></div><div class="col-md-3"><button class="btn btn-primary">Generate</button> <button class="btn btn-secondary" onclick="window.print()">Print</button></div></form></div>
<div class="card p-3"><h5><?= ucfirst(e($type)) ?> Report (<?= e($from) ?> to <?= e($to) ?>)</h5>
<?php if($type==='sales'): ?><table class="table"><thead><tr><th>Invoice</th><th>Customer</th><th>Total</th><th>Date</th></tr></thead><tbody><?php $t=0; foreach($sales as $r): $t+=$r['total_amount']; ?><tr><td><?= e($r['invoice_no']) ?></td><td><?= e($r['cust']) ?></td><td><?= money($r['total_amount']) ?></td><td><?= e($r['sale_date']) ?></td></tr><?php endforeach; ?></tbody></table><strong>Total: <?= money($t) ?></strong><?php endif; ?>
<?php if($type==='purchases'): ?><table class="table"><thead><tr><th>Purchase</th><th>Supplier</th><th>Total</th><th>Date</th></tr></thead><tbody><?php $t=0; foreach($purchases as $r): $t+=$r['total_amount']; ?><tr><td><?= e($r['purchase_no']) ?></td><td><?= e($r['supp']) ?></td><td><?= money($r['total_amount']) ?></td><td><?= e($r['purchase_date']) ?></td></tr><?php endforeach; ?></tbody></table><strong>Total: <?= money($t) ?></strong><?php endif; ?>
<?php if($type==='inventory'): ?><table class="table"><thead><tr><th>SKU</th><th>Product</th><th>Warehouse</th><th>Qty</th></tr></thead><tbody><?php foreach($stock as $r): ?><tr><td><?= e($r['sku']) ?></td><td><?= e($r['name']) ?></td><td><?= e($r['wname']) ?></td><td><?= (int)$r['quantity'] ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?>
<?php if($type==='movements'): ?><table class="table"><thead><tr><th>Type</th><th>Product</th><th>Warehouse</th><th>Qty</th><th>Ref</th><th>Date</th></tr></thead><tbody><?php foreach($moves as $r): ?><tr><td><?= e($r['movement_type']) ?></td><td><?= e($r['pname']) ?></td><td><?= e($r['wname']) ?></td><td><?= (int)$r['quantity'] ?></td><td><?= e($r['reference']??'') ?></td><td><?= e($r['created_at']) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?>
</div>
<?php require_once __DIR__.'/../includes/footer.php'; ?>
